#!/usr/bin/env python3
# Self-contained launcher for the audited Phase 208 patcher source.
import base64
import gzip
import hashlib
from pathlib import Path

_SOURCE_SHA256 = "8cd3f55f067237d1f60af25192ee0336cb84d2ab27bfdcb402ad9ef0644a7b9c"
_PAYLOAD = ""
_source = gzip.decompress(base64.b64decode(_PAYLOAD))
if hashlib.sha256(_source).hexdigest() != _SOURCE_SHA256:
    raise SystemExit("Phase208 embedded patcher checksum mismatch")
_namespace = {"__name__": "__main__", "__file__": str(Path(__file__))}
exec(compile(_source, str(Path(__file__)), "exec"), _namespace)
